143: /* ---------- school geometry ---------- */
144: function buildSchool() {
145:   const floorMat = new THREE.MeshStandardMaterial({ color: 0x212126, roughness: 0.95 });
146:   const floor = new THREE.Mesh(new THREE.PlaneGeometry(44, 44), floorMat);
147:   floor.rotation.x = -Math.PI / 2;
148:   floor.receiveShadow = true;
149:   scene.add(floor);
150: 
151:   const wallMat = new THREE.MeshStandardMaterial({ color: 0xeae6dc, roughness: 0.85 });
152:   function wall(x, y, z, ry, sx = 10, sy = 1, sz = 1) {
153:     const m = new THREE.Mesh(new THREE.BoxGeometry(4 * sx, 3.4 * sy, 0.2 * sz), wallMat);
154:     m.position.set(x, y, z);
155:     m.rotation.y = ry;
156:     m.receiveShadow = true;
157:     scene.add(m);
158:     wallMeshes.push(m);
159:     return m;
160:   }
161:   wall(0, 1.7, -22, 0);          // back
162:   wall(-22, 1.7, 0, Math.PI / 2); // left
163:   wall(22, 1.7, 0, Math.PI / 2);  // right
164:   wall(-7, 1.7, 0, 0);            // front left
165:   wall(7, 1.7, 0, 0);             // front right
166: 
167:   // classroom doors along left side
168:   const doorMat = new THREE.MeshStandardMaterial({ color: 0x5d4037, roughness: 0.8 });
169:   for (let z = -6; z >= -18; z -= 4.6) {
170:     const door = new THREE.Mesh(new THREE.BoxGeometry(1.5, 2.4, 0.16), doorMat);
171:     door.position.set(-20.9, 1.2, z);
172:     door.rotation.y = Math.PI / 2;
173:     door.castShadow = true;
174:     door.receiveShadow = true;
175:     scene.add(door);
176:     interactables.push({ mesh: door, text: '교실 문', dist: 3.2 });
177:   }
178: 
179:   // classroom interior visible at the end of the hall
180:   const deskMat = new THREE.MeshStandardMaterial({ color: 0x8d6e63, roughness: 0.9 });
181:   for (let r = 0; r < 3; r++) {
182:     for (let c = 0; c < 3; c++) {
183:       const desk = new THREE.Mesh(new THREE.BoxGeometry(1, 0.8, 0.6), deskMat);
184:       desk.position.set(-6 + c * 1.1, 0.55, -20 - r * 1.5);
185:       desk.castShadow = true;
186:       desk.receiveShadow = true;
187:       scene.add(desk);
188:     }
189:   }
190:   const board = new THREE.Mesh(new THREE.BoxGeometry(4.2, 2.4, 0.12), new THREE.MeshStandardMaterial({ color: 0x223a22 }));
191:   board.position.set(-6, 1.3, -25.4);
192:   scene.add(board);
193: 
194:   const chalk = new THREE.Mesh(new THREE.BoxGeometry(0.12, 0.5, 0.12), new THREE.MeshStandardMaterial({ color: 0xffffff }));
195:   chalk.position.set(-8.2, 1.1, -25.45);
196:   scene.add(chalk);
197: 
